class Patient {
  + name : string
}

class Family {
  + name : string
}

class Doctor {
  + name : string
}

class Appointment {
  + date : date
  + time : time
}

class Visit {
  + diagnosis : string
  + treatment : string
}

class Medication {
  + name : string
}

class Prescription {
}

Family "1" -- "*" Patient : contains
Family "1" -- "0..1" Doctor : has primary care physician
Patient "1" -- "*" Appointment : schedules
Patient "1" -- "*" Visit : undergoes
Appointment "0..1" -- "0..1" Visit : results in
Visit "1" *-- "0..*" Prescription : includes
Prescription "1" -- "*" Medication : contains
Visit "0..*" -- "0..*" Doctor : is seen by

@enduml

